12	/**
13	 * Assigns a shared {@code householdId} when a create request opts in with
14	 * {@code sharesHousehold: true}, joining an existing owner at the same household — the
15	 * same {@code lastName} (compared case-insensitively with collapsed whitespace) and the
16	 * same {@code address} in its normalized form (see {@link AddressNormalizer}), matching
17	 * {@link EnsureUniqueHousehold}.
18	 *
19	 * <p>The identifier is derived deterministically from the normalized last name and
20	 * address, so every owner of a household computes the same value regardless of creation
21	 * order — a stable shared identifier. Existing same-household owners that do not yet
22	 * carry one are back-filled so both sides share it.
23	 *
24	 * <p>Runs after {@link BuildOwner} (which produces the {@link Owner}) and before
25	 * {@link SaveOwner}; it mutates the built owner in place (see {@code @Val} semantics).
26	 */
27	public class AssignHousehold {
28	
29	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
30	            OwnerRepository ownerRepository) {
31	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
32	            return;
33	        }
34	        String lastName = normalize(owner.getLastName());
35	        String address = normalizeAddress(owner.getAddress());
36	        String householdId = householdId(lastName, address);
37	        owner.setHouseholdId(householdId);
38	        for (Owner existing : ownerRepository.findAll()) {
39	            if (lastName.equals(normalize(existing.getLastName()))
40	                    && address.equals(normalizeAddress(existing.getAddress()))
41	                    && existing.getHouseholdId() == null) {
42	                existing.setHouseholdId(householdId);
43	                ownerRepository.save(existing);
44	            }
45	        }
46	    }
47	
48	    /** Stable 16-char upper-case hex identifier over the normalized last name and address. */
49	    private static String householdId(String lastName, String address) {
50	        return sha256hex(lastName + "|" + address).substring(0, 16).toUpperCase();
51	    }
